import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"宿主服务","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/sdk/services.md","filePath":"zh-CN/dev-guide/sdk/services.md","lastUpdated":1785993908000}'),r={name:"zh-CN/dev-guide/sdk/services.md"};function a(i,e,s,l,n,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="宿主服务" tabindex="-1">宿主服务 <a class="header-anchor" href="#宿主服务" aria-label="Permalink to &quot;宿主服务&quot;">​</a></h1><p><code>PluginSdk.Services</code> 里的静态服务，把宿主应用的功能暴露给插件——每一个都是包装了宿主启动时接好的委托的薄静态类，所以不管底层实际运行的是什么，插件的调用方式都一样。</p><table tabindex="0"><thead><tr><th>服务</th><th>用途</th></tr></thead><tbody><tr><td><code>FuzzyMatchService</code></td><td><code>IsMatch(pattern, text)</code> —— <code>text</code>(或它的某个别名)是否匹配 fzf 语法的 <code>pattern</code>,用的是和宿主自身搜索完全一致的匹配逻辑;<code>GetHighlightMask(text, query)</code> —— 对应这一对 (text, query) 的逐字符高亮掩码,用的是宿主自己那套字面量/模糊/别名多级兜底算法(含中文拼音),这样插件自己结果的高亮就能和其他结果保持一致,而不是只能处理简单的字面量子串匹配。</td></tr><tr><td><code>TranslationService</code></td><td><code>Get(key)</code> / <code>Format(key, args)</code> 在运行时按当前语言查询;<code>LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> 加载插件自己内嵌的 JSON 语言包;<code>GetSupportedCultures(assembly)</code>;<code>GetCurrentCulture()</code> —— 应用当前选定的界面语言(比如 <code>&quot;zh-CN&quot;</code>),这是一个独立于操作系统语言的用户设置。只有你确实需要拿到原始语言代码本身时才用它(比如塞进 HTTP 的 <code>Accept-Language</code> 请求头,或者决定翻译 API 的目标语言)——<code>CultureInfo.CurrentUICulture</code> 反映的是操作系统的语言,不是这个设置,一旦用户的 Windows 语言和应用内语言不一致,两者就会悄悄对不上。</td></tr><tr><td><code>IconService</code></td><td><code>GetIcon(path, isDir)</code> 和 <code>GetThumbnail(path, size)</code> —— 带缓存的 Shell 图标/缩略图提取，插件不需要自己调 Windows 图标 API。</td></tr><tr><td><code>FavoritesService</code></td><td><code>GetFavorites()</code> —— 只读访问用户的<a href="./../../user-guide/settings/favorites.html">收藏夹</a>列表(<code>FavoriteItem</code>:Name、Path)。</td></tr><tr><td><code>HistoryService</code></td><td><code>GetHistoryEntries()</code> —— 每一条已记录的<a href="./../../user-guide/settings/history.html">历史记录</a>条目,按最近打开优先排序,类型是 <code>HistoryEntry { Keyword, Path, Kind, Time }</code>(<code>Kind</code> 是 <code>HistoryEntryKind</code>:<code>File</code> / <code>Folder</code> / <code>Application</code>;<code>Keyword</code> 是打开时输入框里的搜索文字,没打字就直接打开的话(比如从快速面板的标签里点开)就是空字符串;<code>Time</code> 是 Unix 秒)。同一个路径最多只会出现一次,归属于最近一次带它进来的那个关键字。</td></tr><tr><td><code>FileMetadataService</code></td><td><code>GetMetadataAsync(paths)</code> —— 批量查询 Size/Created/Modified/Accessed(<a href="./abstractions.html#filemetadata"><code>FileMetadata</code></a>)，用于查询<strong>不属于</strong>你当前结果集的路径——每个 <code>ISearchResult</code> 本身就通过自己的 <code>Metadata</code> 属性免费携带这些数据(参见<a href="./abstractions.html#isearchresult">共享抽象契约</a>)，所以只有拿到的路径不是来自结果对象(比如来自你自己的配置)时才需要用这个服务。</td></tr><tr><td><code>DirectoryIndexerService</code></td><td><code>RegisterDirectory(pluginId, path, recursive, filterPattern)</code> / <code>UnregisterDirectories(pluginId)</code> / <code>SearchDirectoriesAsync(pluginId, query, token)</code> —— 让插件注册自己的目录进行后台索引和 USN 监听，而不用自己重新实现这套机制。<code>WatchDirectories(pluginId, onChanged)</code> 会在<strong>你自己注册的</strong>目录发生磁盘变化时回调你，返回一个 <code>IDisposable</code> 用于退订。它是按注册方投递而不是广播：没有 id 要比对，也不会误处理别人的变化——变化落在谁的注册上，宿主本来就知道。回调在后台线程触发，并且已经做过防抖(一次批量拷贝在目录安静下来后只回调一次，而不是每个文件一次)；只有宿主能确实归因到你的目录的变化才会通知，归因不了时(比如整树被重新扫描替换)宁可通知你也不会保持沉默。<code>EnumerateDirectoryAsync(path, recursive, filterPattern, limit, token)</code> 从同一份索引(而不是文件系统)列出某个目录的内容——宿主已索引的盘完全不产生磁盘 I/O，没索引的目录则自动改为实时遍历，调用方不需要自己判断属于哪种情况。它是流式的；<code>filterPattern</code> 筛的是<strong>文件</strong>(目录一律返回，不需要就按 <code>IsDir</code> 过滤)；隐藏和系统条目永远不返回；递归列举时值得设 <code>limit</code>——<code>EnumerateDirectoryAsync(@&quot;C:\\&quot;, recursive: true)</code> 会老老实实把整个卷的每一条都交给你。</td></tr><tr><td><code>RecentFilesService</code></td><td><code>GetRecentFilesAsync(directories, limit, maxAgeMinutes, token)</code> —— 一组目录下最新的条目，最近的在前，由宿主的内存索引回答而不是去读磁盘。是把这些目录当作<strong>一份</strong>合并列表，而不是每个目录一份。只含文件：文件夹自己的修改时间在里面增删任何东西时都会变，那会把「正在其中工作」的文件夹顶到一份本该显示「工作了什么」的列表最前面。<code>limit</code> 传 0 表示不限条数，<code>maxAgeMinutes</code> 传 0 表示不限时间，但两个都不设的话，一个闲置的文件夹会仅仅因为没有更新的东西就一直端出一个月前的文件。宿主没有索引的目录不会被实时遍历，而是干脆不贡献任何条目——这里要的是快答案，要么没有；慢的那条路请用 <code>DirectoryIndexerService.EnumerateDirectoryAsync</code>。</td></tr><tr><td><code>ExplorerPathService</code></td><td><code>GetLastActivePath()</code> —— 资源管理器窗口或文件对话框最后显示的那个文件夹，从来没有过则为 <code>null</code>。它由宿主自己的窗口跟踪填入，跟的是<strong>所有</strong>应用的文件对话框，而不只是 Lertaro 自己的界面，所以它的含义是「用户最后真正在看的那个文件夹」——这是插件自己算不出来的。方向和 <a href="./core-search-actions.html"><code>IActivePathCollector</code></a> 相反：那个是插件<strong>告诉</strong>宿主某个第三方文件管理器正在显示什么，这个是向宿主打听。不保证仍然存在：它记的是用户去过哪，而那个文件夹可能早已被删掉或拔掉了。</td></tr><tr><td><code>PluginSettingsService</code></td><td><code>GetSetting&lt;T&gt;(pluginId, key, defaultValue)</code> —— 从宿主的配置存储里只读访问插件自己持久化的设置。回退分三层:用户存过就用持久化的值;没存过就用你 <code>IConfigurable</code> schema 里该字段自己声明的 <code>DefaultValue</code>;两者都没有才轮到你传进来的 <code>defaultValue</code> 兜底——这样 schema 里声明的默认值就是唯一权威来源,调用方不需要在代码里再手写一份重复的默认值。如果你把某个设置缓存了起来而不是每次都重新读取,记得订阅 <code>SettingChanged(pluginId, key)</code> 事件,在它为你的插件触发时清空缓存——宿主是在设置页保存之后立刻触发这个事件的,这是唯一可靠的失效时机(不管是按键触发还是轮询检查,都要等到别的什么东西凑巧触发了才会看到变化,或者干脆永远看不到)。</td></tr><tr><td><code>SearchRefreshService</code></td><td><code>RefreshIfMatches(queryMatches)</code> —— 给数据是异步到达的 <code>IInstantResultProvider</code> 用的(参见 <a href="./core-search-actions.html#iinstantresultprovider"><code>IInstantResultProvider</code></a>):等你的后台请求完成、结果也缓存好之后，调用这个方法并传入一个基于当前查询文字的判断函数，宿主会把所有匹配这个判断的、正在进行的搜索重新跑一遍，这样刚缓存好的结果就能直接显示出来，不需要用户重新输入。</td></tr><tr><td><code>Logger</code></td><td><code>Log(message, level = LogLevel.Info)</code> —— 写入 App 的日志文件，和宿主自己的日志行一样，显示在<strong>设置 → 运行状态 → App</strong> 里。</td></tr><tr><td><code>PluginPromptService</code></td><td><code>Prompt(title, fields, initialValues?)</code> —— 弹出一个小的模态窗口，向用户询问给定<a href="./abstractions.html#iconfigurable"><code>PluginConfigField</code></a>字段的值(用的正是 <code>IConfigurable</code> 的配置对话框那套字段 schema/渲染逻辑)，按 <code>Key</code> 匹配从 <code>initialValues</code> 预填，没有就用各字段自己的 <code>DefaultValue</code>。返回按字段 <code>Key</code> 索引的填写结果，用户取消则返回 <code>null</code>——这些值不会读取或写入插件真正持久化的设置，所以可以放心复用某个配置字段的 schema 单纯做一次性输入(比如&quot;添加前先给它起个名字&quot;)，不会碰到背后真实的那个设置项。</td></tr></tbody></table><p><code>LogLevel</code> 是 <code>Error</code> / <code>Warn</code> / <code>Info</code> / <code>Debug</code>，与<a href="./../../user-guide/settings/service-status.html">运行状态日志查看器</a>里的等级过滤器一致。</p><h2 id="shell-文件操作" tabindex="-1">Shell 文件操作 <a class="header-anchor" href="#shell-文件操作" aria-label="Permalink to &quot;Shell 文件操作&quot;">​</a></h2><p><code>Lertaro.PluginSdk.Shell.FileOperations</code> —— 对 Windows shell 自己的 <code>IFileOperation</code> 的一层薄封装。插件搬动文件时，用户看到的是和资源管理器一模一样的进度对话框、「文件已存在」提示和撤销记录，而不是一次行为略有不同的 <code>System.IO</code> 调用。</p><table tabindex="0"><thead><tr><th>帮助类</th><th>用途</th></tr></thead><tbody><tr><td><code>ShellPasteHelper</code></td><td><code>PasteAsync(sourcePaths, destinationFolder, move, onCompleted?)</code> —— 把任意多个路径复制(或移动)进同一个文件夹，合并成<strong>一次</strong> shell 操作，所以跨盘的多选也只弹一个对话框，而不是每个文件一个。发出即返回：native 对话框可能被用户晾在那里，阻塞调用方只会把界面冻住。<code>onCompleted</code> 在操作结束时触发——不管是复制完了还是用户取消了，因为对一个正显示目标文件夹的视图来说，这两种情况的应对是同一个：回去重新看一眼。</td></tr><tr><td><code>ShellDeleteHelper</code></td><td><code>DeleteAsync(paths, permanent)</code> —— 放进回收站或永久删除，同样合并成一次操作、一次确认。同样是发出即返回。</td></tr><tr><td><code>VirtualFileExtractor</code></td><td><code>HasVirtualFiles(dataObject)</code> / <code>Extract(dataObject, targetFolder)</code> —— 把拖动携带的、磁盘上还不存在的文件写出来：从浏览器拖出的图片、从邮件客户端拖出的附件、从压缩包预览里拖出的文件。它们都不是路径，所以 <code>IDataObject.GetData(DataFormats.FileDrop)</code> 什么也拿不到；真正到来的是一份列出文件名的描述符，加上按索引一次给一个的字节流，这个类做的就是把它拆出来。刻意不按类型过滤：拒绝拖动方愿意交出来的东西，意味着要么信扩展名、要么嗅探字节，这两件事都不该由它来做。<code>ResolveDestination(folder, name)</code> 是它「重名就加 (2) 而不是覆盖」的那套命名规则，单独暴露出来给自己写文件的调用方用。</td></tr></tbody></table><p>两个异步帮助类都跑在 SDK 自己的 STA 工作线程上(<code>ShellOperationStaWorker</code>，由宿主启动)——shell 的 COM 接口要求 STA，共用一条意味着插件不必自己开一个套间。</p>',8)])])}const p=t(r,[["render",a]]);export{g as __pageData,p as default};
